// android/ is gitignored and regenerated by every `expo prebuild`, which
// means it always comes back with the React Native scaffold's debug-only
// signingConfigs -- `release { signingConfig signingConfigs.debug }`.
// That's fine for a local test APK but can never be submitted anywhere
// real (and once something IS published with a given key, every future
// update must be signed with that exact same key forever, so this isn't
// something to regenerate casually).
//
// The actual keystore lives in mobile/release-keys/ (gitignored, never
// committed -- see release-keys/credentials.txt, also gitignored, for
// the store password). This plugin copies it into the generated
// android/app/ directory and rewrites build.gradle's release
// signingConfig to use it, reading the password from the
// RELEASE_KEYSTORE_PASSWORD env var at build time rather than ever
// hardcoding it into a generated (and gitignored, but still local-disk)
// file.
//
// No-op if the keystore doesn't exist on this machine (e.g. a fresh
// clone before anyone's generated one) -- release builds there just
// keep using the debug signingConfig as before, same as if this plugin
// didn't exist.
const fs = require('fs');
const path = require('path');
const { withDangerousMod, withAppBuildGradle } = require('expo/config-plugins');

const KEYSTORE_SRC = path.join(__dirname, '..', 'release-keys', 'release.keystore');
const KEY_ALIAS = 'agro-mirai-release';

module.exports = function withReleaseSigning(config) {
  if (!fs.existsSync(KEYSTORE_SRC)) return config;

  config = withDangerousMod(config, [
    'android',
    (cfg) => {
      const dest = path.join(cfg.modRequest.platformProjectRoot, 'app', 'release.keystore');
      fs.copyFileSync(KEYSTORE_SRC, dest);
      return cfg;
    },
  ]);

  return withAppBuildGradle(config, (cfg) => {
    const src = cfg.modResults.contents;

    // Add a release signingConfig entry, right after the existing debug
    // one (inside the same signingConfigs {} block).
    const signingConfigsMarker = /(signingConfigs\s*\{\s*debug\s*\{[\s\S]*?\n\s*\})/;
    if (!signingConfigsMarker.test(src)) {
      throw new Error('withReleaseSigning: could not find signingConfigs.debug block to anchor on');
    }
    let out = src.replace(signingConfigsMarker, (debugBlock) => `${debugBlock}
        release {
            storeFile file('release.keystore')
            storePassword System.getenv("RELEASE_KEYSTORE_PASSWORD")
            keyAlias '${KEY_ALIAS}'
            keyPassword System.getenv("RELEASE_KEYSTORE_PASSWORD")
        }`);

    // The release buildType starts out pointing at signingConfigs.debug
    // (the RN/Expo scaffold default) -- point it at the real one instead.
    // Anchored on the "Caution" comment that precedes it in the scaffold
    // template, since the debug buildType has its own, earlier
    // "signingConfig signingConfigs.debug" line this must not touch.
    const releaseSigningLine = /(\/\/ see https:\/\/reactnative\.dev\/docs\/signed-apk-android\.\s*\n\s*)signingConfig signingConfigs\.debug/;
    if (!releaseSigningLine.test(out)) {
      throw new Error('withReleaseSigning: could not find the release buildType signingConfig line to replace');
    }
    out = out.replace(releaseSigningLine, '$1signingConfig signingConfigs.release');

    cfg.modResults.contents = out;
    return cfg;
  });
};
